test('an entry-unreachable end node with an uncloneable result is still checked', () => {
  const workflow = {
    id: 'unreachable-end', entry: 'start',
    nodes: [
      { id: 'start', type: 'trigger', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
